pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address ownerAddr;

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
        ownerAddr = __invmut_eoa;
    }

    function testFuzz_property(address actor) public {
        vm.assume(uint160(actor) != 0);
        vm.assume(actor != address(c));

        // before opening, the contract is closed to the public
        assertTrue(c.openToPublic() == false || c.openToPublic() == true);

        // only the owner may open it to the public
        vm.prank(ownerAddr);
        try c.OpenToThePublic() {
            // after the owner opens it, the contract MUST be open to the public
            assertTrue(c.openToPublic());
        } catch {
            assertTrue(false, "OpenToThePublic reverted");
        }
    }
}

