pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner_ = address(uint160(0xE0A));

    function setUp() public {
        address __invmut_eoa = address(uint160(0xE0A));
        vm.deal(__invmut_eoa, 100 ether);
        vm.startPrank(__invmut_eoa, __invmut_eoa);
        c = new C(address(this), 0);
        vm.stopPrank();
    }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount < 50 ether);
        vm.assume(actor != address(0) && actor.code.length == 0);

        vm.deal(actor, amount);

        vm.startPrank(owner_, owner_);
        c.AdjustBetAmounts(amount);
        c.OpenToThePublic();
        vm.stopPrank();

        vm.startPrank(actor, actor);
        bool ok = true;
        try c.wager{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(ok && c.hasPlayerWagered(actor));
    }
}

